// TypeScript Version: 4.1

/**
* Divides two half-precision floating-point numbers.
*
* @param x - first input value
* @param y - second input value
* @returns result
*
* @example
* var v = div( -1.0, 5.0 );
* // returns ~-0.2
*
* @example
* v = div( 2.0, 5.0 );
* // returns ~0.4
*
* @example
* v = div( 0.0, 5.0 );
* // returns 0.0
*
* @example
* v = div( -0.0, 5.0 );
* // returns -0.0
*
* @example
* v = div( NaN, NaN );
* // returns NaN
*/
declare function div( x: number, y: number ): number;


// EXPORTS //

export = div;
